customCSS:
.t, .history { color: #575860; }
.join { color: #81b29a; }
.part, .quit { color: #575860; }
.kick, .error { color: #c94f6d; }
.notice { color: #dbc074; }
.action { color: #9d79d6; }
.mode, .nick, .topic, .server { color: #63cdcf; }
.highlight { color: #cdcecf; background-color: #2b3b51; border-left: 3px solid #9d79d6; padding-left: 8px; }
.reply { color: #575860; border-left: 2px solid #719cd6; padding-left: 6px; }
.oper { color: #192330; background-color: #dbc074; }
.reactions { color: #719cd6; background-color: #393b44; }
.card { background-color: #393b44; border-color: #575860; }
.card-title { color: #719cd6; }
.card-desc { color: #575860; }
.daychange { color: #575860; border-color: #393b44; }
